/* ==============================================================
   Objeto ..........: dbo.IV$S_PESSOA
   Tipo ............: VIEW
   Criado em .......: 2025-02-17 17:35:37
   Modificado em ...: 2025-02-17 17:35:37
   Linhas ..........: 1
   Escreve em tabela: nao
   Tabelas referidas: GE_PESSOA
   Fonte: banco CRM (Vortice CRM / Tracbel) - extracao somente leitura
   ============================================================== */

 Create VIEW IV$S_PESSOA(  SEQPESSOA, VERSAO, STATUS, NOMERAZAO, FANTASIA,          FISICA_JURIDICA, SEXO, CIDADE, UF, PAIS,          BAIRRO, LOGRADOURO, FONEDDD1, FONENRO1, FONEDDD2,          FONENRO2, FONEDDD3, FONENRO3, FAXDDD, FAXNRO,          NROCGCCPF, DIGCGCCPF, INSCRICAORG, DTANASCFUND, ORIGEM,          EMAIL, HOMEPAGE, CXPOSTAL, ESTADO_CIVIL, ATIVIDADE,          RENDA_FATURAMENTO, GRAU_INSTRUCAO, GRUPO, DTAINCLUSAO, USUINCLUSAO,          DTAALTERACAO, USUALTERACAO, VENDEDOR, RECEBE_TELEFONEMA, RECEBE_CORRESPONDENCIA,          TEM_PROBLEMACREDITO, POSSUI_EMAIL, RECEBE_EMAIL, DIA_NASC, MES_NASC,          ANO_NASC)   AS   SELECT SEQPESSOA, VERSAO,         CASE STATUS           WHEN 'P' THEN 'PROSPECT'           WHEN 'F' THEN'FALECIDO'           WHEN 'I' THEN 'INATIVO'           WHEN 'O' THEN 'OUTRO'           WHEN 'S' THEN 'SUSPECT'           WHEN 'A' THEN  'ATIVO'        ELSE '???'           END AS STATUS,         NOMERAZAO, FANTASIA,         CASE FISICAJURIDICA WHEN 'F' THEN 'FÍSICA' WHEN  'J' THEN 'JURÍDICA' ELSE '' END AS FISICA_JURIDICA,        SEXO,  CIDADE, UF, PAIS,         BAIRRO, LOGRADOURO,  FONEDDD1,  FONENRO1,         FONEDDD2, FONENRO2,  FONEDDD3, FONENRO3,          FAXDDD, FAXNRO, NROCGCCPF, DIGCGCCPF,         INSCRICAORG, DTANASCFUND, ORIGEM,          EMAIL, HOMEPAGE, CXPOSTAL,         CASE ESTADOCIVIL              WHEN 'C' THEN 'CASADO'             WHEN 'S' THEN 'SOLTEIRO'             WHEN 'D' THEN 'DIVORCIADO'             WHEN 'Q' THEN 'DESQUITADO'             WHEN 'V' THEN 'VIÚVO'               ELSE 'NÃO INFORMADO'             END   AS ESTADO_CIVIL,        ATIVIDADE, RENDAFATURAMENTO AS RENDA_FATURAMENTO,         GRAUINSTRUCAO AS GRAU_INSTRUCAO, GRUPO,           DTAINCLUSAO, USUINCLUSAO, DTAALTERACAO, USUALTERACAO,          CODVENDEDOR AS VENDEDOR,         CASE TELEFONEMA WHEN 1 THEN 'SIM' ELSE 'NÃO' END AS RECEBE_TELEFONEMA,         CASE CORRESPONDENCIA WHEN 1 THEN 'SIM' ELSE 'NÃO' END AS RECEBE_CORRESPONDENCIA,         CASE PROBLEMACREDITO WHEN 1 THEN 'SIM' ELSE 'NÃO' END AS TEM_PROBLEMACREDITO,         CASE NAOPOSSUIEMAIL WHEN 1 THEN 'SIM' ELSE 'NÃO' END AS POSSUI_EMAIL,         CASE RECEBEEMAIL WHEN 1 THEN 'SIM' ELSE 'NÃO' END AS POSSUI_EMAIL,           DAY(DTANASCFUND ) AS DIA_NASC,        MONTH(DTANASCFUND ) AS MES_NASC,         YEAR(DTANASCFUND ) AS ANO_NASC FROM GE_PESSOA   